import{_ as p,a0 as l,w as r,s as n,I as e,x as s,a1 as o,A as a,ao as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"如何恢复丢弃的 git stash 数据 | LCTT x X-CMD","titleTemplate":false,"description":"如何恢复丢弃的 git stash 数据 | LCTT (201708) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何恢复丢弃的 git stash 数据 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何恢复丢弃的 git stash 数据 | LCTT (201708) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201708/20170818 How to recover from a git mistake","title":"如何恢复丢弃的 git stash 数据","tag":"201708","desc":""},"relativePath":"201708/20170818 How to recover from a git mistake.md","filePath":"[post].md"}'),g={name:"201708/20170818 How to recover from a git mistake.md"};function u(m,t,f,h,c,k){const i=l("Link");return r(),n("div",null,[t[24]||(t[24]=e("h1",{id:"如何恢复丢弃的-git-stash-数据",tabindex:"-1"},[s("如何恢复丢弃的 git stash 数据 "),e("a",{class:"header-anchor",href:"#如何恢复丢弃的-git-stash-数据","aria-label":"Permalink to “如何恢复丢弃的 git stash 数据”"},"​")],-1)),t[25]||(t[25]=e("blockquote",null,[e("p",null,"不要让 git 命令中的错误抹去数天的工作")],-1)),t[26]||(t[26]=e("p",null,[e("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/bubblehands_fromRHT_520_0612LL.png?itok=_iQ2dO3S",alt:"How to recover from a git mistake",title:"How to recover from a git mistake"})],-1)),e("p",null,[t[1]||(t[1]=s("今天我的同事几乎失去了他在四天工作中所做的一切。由于不正确的 ",-1)),t[2]||(t[2]=e("code",null,"git",-1)),t[3]||(t[3]=s(" 命令，他把保存在 ",-1)),o(i,{href:"https://www.git-scm.com/docs/git-stash"},{default:a(()=>[...t[0]||(t[0]=[s("stash",-1)])]),_:1}),t[4]||(t[4]=s(" 中的更改删除了。在这悲伤的情节之后，我们试图寻找一种恢复他所做工作的方法，而且我们做到了！",-1))]),t[27]||(t[27]=d('<p>首先警告一下：当你在实现一个大功能时，请将它分成小块并定期提交。长时间工作而不做提交并不是一个好主意。</p><p>现在我们已经搞定了那个错误，下面就演示一下怎样从 stash 中恢复误删的更改。</p><p>我用作示例的仓库中，只有一个源文件 “main.c”，如下所示：</p><p><img src="https://opensource.com/sites/default/files/u128651/missing_data_from_stash_01.jpeg" alt="Repository with one source file" title="Repository with one source file"></p><p>它只有一次提交，即 “Initial commit”：</p><p><img src="https://opensource.com/sites/default/files/u128651/missing_data_from_stash_02.jpeg" alt="One commit" title="One commit"></p><p>该文件的第一个版本是：</p><p><img src="https://opensource.com/sites/default/files/u128651/missing_data_from_stash_03.jpeg" alt="First version of the file" title="First version of the file"></p><p>我将在文件中写一些代码。对于这个例子，我并不需要做什么大的改动，只需要有什么东西放进 stash 中即可，所以我们仅仅增加一行。“git diff” 的输出如下：</p><p><img src="https://opensource.com/sites/default/files/u128651/missing_data_from_stash_04.jpeg" alt="git-diff output " title="git-diff output "></p><p>现在，假设我想从远程仓库中拉取一些新的更改，当时还不打算提交我自己的更改。于是，我决定先 stash 它，等拉取远程仓库中的更改后，再把我的更改恢复应用到主分支上。我执行下面的命令将我的更改移动到 stash 中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git stash</span></span></code></pre></div><p>使用命令 <code>git stash list</code> 查看 stash，在这里能看到我的更改：</p><p><img src="https://opensource.com/sites/default/files/u128651/missing_data_from_stash_06.jpeg" alt="Output of changes in our stash" title="Output of changes in our stash"></p><p>我的代码已经在一个安全的地方，而且主分支目前是干净的（使用命令 <code>git status</code> 检查）。现在我只需要拉取远程仓库的更改，然后把我的更改恢复应用到主分支上，而且我也应该是这么做的。</p><p>但是我错误地执行了命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git stash drop</span></span></code></pre></div><p>它删除了 stash，而不是执行了下面的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git stash pop</span></span></code></pre></div><p>这条命令会在从栈中删除 stash 之前应用它。如果我再次执行命令 <code>git stash list</code>，就能看到在没有从栈中将更改恢复到主分支的之前，我就删除了它。OMG！接下来怎么办？</p><p>好消息是：<code>git</code> 并没有删除包含了我的更改的对象，它只是移除了对它的引用。为了证明这一点，我使用命令 <code>git fsck</code>，它会验证数据库中对象的连接和有效性。这是我对该仓库执行了 <code>git fsck</code> 之后的输出：</p><p><img src="https://opensource.com/sites/default/files/u128651/missing_data_from_stash_07.jpeg" alt="Output after executing the git-fsck command on the repository" title="Output after executing the git-fsck command on the repository"></p><p>由于使用了参数 <code>--unreachable</code>，我让 <code>git-fsck</code> 显示出所有不可访问的对象。正如你看到的，它显示并没有不可访问的对象。而当我从 stash 中删除了我的更改之后，再次执行相同的指令，得到了一个不一样的输出：</p><p><img src="https://opensource.com/sites/default/files/u128651/missing_data_from_stash_08.jpeg" alt="Output after dropping changes on stash" title="Output after dropping changes on stash"></p><p>现在有三个不可访问对象。那么哪一个才是我的更改呢？实际上，我不知道。我需要通过执行命令 <code>git show</code> 来搜索每一个对象。</p><p><img src="https://opensource.com/sites/default/files/u128651/missing_data_from_stash_09.jpeg" alt="Output after executing the git-show command " title="Output after executing the git-show command "></p><p>就是它！ID 号 <code>95ccbd927ad4cd413ee2a28014c81454f4ede82c</code> 对应了我的更改。现在我已经找到了丢失的更改，我可以恢复它。其中一种方法是将此 ID 取出来放进一个新的分支，或者直接提交它。如果你得到了你的更改对象的 ID 号，就可以决定以最好的方式，将更改再次恢复应用到主分支上。对于这个例子，我使用 <code>git stash</code> 将更改恢复到我的主分支上。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git stash apply 95ccbd927ad4cd413ee2a28014c81454f4ede82c</span></span></code></pre></div><p>另外需要重点记住的是 <code>git</code> 会周期性地执行它的垃圾回收程序（<code>gc</code>），它执行之后，使用 <code>git fsck</code> 就不能再看到不可访问对象了。</p>',29)),e("p",null,[e("em",null,[t[6]||(t[6]=s("本文",-1)),o(i,{href:"http://jvanz.com/recovering-missed-data-from-stash.html#recovering-missed-data-from-stash"},{default:a(()=>[...t[5]||(t[5]=[s("最初发表",-1)])]),_:1}),t[7]||(t[7]=s("于作者的博客，并得到了转载授权。",-1))])]),e("p",null,[t[9]||(t[9]=s("（题图：opensource.com，附图：José Guilherme Vanz, ",-1)),o(i,{href:"https://creativecommons.org/licenses/by/4.0/"},{default:a(()=>[...t[8]||(t[8]=[s("CC BY",-1)])]),_:1}),t[10]||(t[10]=s("）",-1))]),t[28]||(t[28]=e("hr",null,null,-1)),e("p",null,[t[12]||(t[12]=s("via: ",-1)),o(i,{href:"https://opensource.com/article/17/8/recover-dropped-data-stash"},{default:a(()=>[...t[11]||(t[11]=[s("https://opensource.com/article/17/8/recover-dropped-data-stash",-1)])]),_:1})]),e("p",null,[t[16]||(t[16]=s("作者：",-1)),o(i,{href:"https://opensource.com/users/jvanz"},{default:a(()=>[...t[13]||(t[13]=[s("Jose Guilherme Vanz",-1)])]),_:1}),t[17]||(t[17]=s(" 译者：",-1)),o(i,{href:"https://github.com/firmianay"},{default:a(()=>[...t[14]||(t[14]=[s("firmianay",-1)])]),_:1}),t[18]||(t[18]=s(" 校对：",-1)),o(i,{href:"https://github.com/wxy"},{default:a(()=>[...t[15]||(t[15]=[s("wxy",-1)])]),_:1})]),e("p",null,[t[21]||(t[21]=s("本文由 ",-1)),o(i,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[19]||(t[19]=[s("LCTT",-1)])]),_:1}),t[22]||(t[22]=s(" 原创编译，",-1)),o(i,{href:"https://linux.cn/"},{default:a(()=>[...t[20]||(t[20]=[s("Linux中国",-1)])]),_:1}),t[23]||(t[23]=s(" 荣誉推出",-1))])])}const T=p(g,[["render",u]]);export{C as __pageData,T as default};
